 return <View {...rest} style={[{gap:space[2]},style]} accessibilityLabel="PDF signature stamp"><View style={{flexDirection:'row',gap:space[2],flexWrap:'wrap'}}>{(['ink','image'] as const).map(m=><Button key={m} title={m==='ink'?'Draw signature':'Image signature'} variant="secondary" accessibilityState={{selected:m===mode}} disabled={off} unstyled={unstyled} onPress={()=>guard.current()?.onModeChange(m)}/>)}</View>
